/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_validate_profile_limit` BEFORE INSERT ON `profile` FOR EACH ROW BEGIN
    DECLARE allowed_count INT DEFAULT NULL;
    DECLARE current_count INT DEFAULT 0;
    SELECT MAX(sp.max_profiles)
    INTO allowed_count
    FROM subscription AS s
    JOIN subscription_plan AS sp
        ON s.plan_id = sp.plan_id
    WHERE s.user_id = NEW.user_id
      AND s.status = 'ACTIVE'
      AND s.start_date <= CURDATE()
      AND (s.end_date IS NULL OR s.end_date >= CURDATE());
    IF allowed_count IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'An active subscription is required';
    ELSE
        SELECT COUNT(*)
        INTO current_count
        FROM profile
        WHERE user_id = NEW.user_id;
        IF current_count >= allowed_count THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Profile limit exceeded';
        END IF;
    END IF;
END */;;
DELIMITER ;
