/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_validate_watch_duration` BEFORE INSERT ON `watch_history` FOR EACH ROW BEGIN
    DECLARE max_duration INT;
    SELECT duration
    INTO max_duration
    FROM content
    WHERE content_id = NEW.content_id;
    IF NEW.watch_duration IS NOT NULL
       AND max_duration IS NOT NULL
       AND NEW.watch_duration > max_duration THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Watch duration exceeds content duration';
    END IF;
END */;;
DELIMITER ;
