/*!50001 DROP VIEW IF EXISTS `v_active_subscriptions`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_0900_ai_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_active_subscriptions` AS select `u`.`user_id` AS `user_id`,`u`.`username` AS `username`,`sp`.`plan_name` AS `plan_name`,`sp`.`price` AS `price`,`sp`.`quality` AS `quality`,`sp`.`max_profiles` AS `max_profiles`,`s`.`start_date` AS `start_date`,`s`.`end_date` AS `end_date` from ((`subscription` `s` join `users` `u` on((`s`.`user_id` = `u`.`user_id`))) join `subscription_plan` `sp` on((`s`.`plan_id` = `sp`.`plan_id`))) where ((`s`.`status` = 'ACTIVE') and (`s`.`start_date` <= curdate()) and ((`s`.`end_date` is null) or (`s`.`end_date` >= curdate()))) */;
