/*!50001 VIEW `v_profile_watch_history` AS select `p`.`profile_id` AS `profile_id`,`p`.`profile_name` AS `profile_name`,`c`.`content_id` AS `content_id`,`c`.`title` AS `title`,`w`.`watch_duration` AS `watch_duration`,`w`.`completed` AS `completed` from ((`watch_history` `w` join `profile` `p` on((`p`.`profile_id` = `w`.`profile_id`))) join `content` `c` on((`c`.`content_id` = `w`.`content_id`))) */;
